#include <iostream>
#include <string>
#include <unordered_set>
using namespace std;
typedef unsigned long long ull;
const ull B1=131, M1=(1ULL<<61)-1, B2=137, M2=(1ULL<<31)-1;
ull addmod(ull a,ull b,ull m){a+=b;return a>=m?a-m:a;}
ull mulmod61(ull a,ull b){
    __uint128_t r=(__uint128_t)a*b;
    ull res=(ull)(r>>61)+(ull)(r&M1);
    return res>=M1?res-M1:res;
}
int main(){
    ios_base::sync_with_stdio(false);cin.tie(NULL);
    string s;int k; cin>>s>>k;
    int n=s.size();
    if(k>n){cout<<0;return 0;}
    ull h1=0,h2=0,p1=1,p2=1;
    for(int i=0;i<k;i++){
        h1=addmod(mulmod61(h1,B1),s[i],M1);
        h2=(h2*B2+s[i])%M2;
        if(i>0){p1=mulmod61(p1,B1);p2=p2*B2%M2;}
    }
    unordered_set<ull> seen;
    seen.insert(h1^(h2<<32));
    for(int i=1;i<=n-k;i++){
        h1=mulmod61(addmod(h1,M1-mulmod61(p1,(ull)s[i-1]),M1),B1);
        h1=addmod(h1,(ull)s[i+k-1],M1);
        h2=(h2-p2*(ull)s[i-1]%M2+M2)*B2%M2;
        h2=(h2+(ull)s[i+k-1])%M2;
        seen.insert(h1^(h2<<32));
    }
    cout<<seen.size()<<"\n";
    return 0;
}

