import java.util.*;
import java.io.*;
public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        String s=br.readLine().trim();
        int k=Integer.parseInt(br.readLine().trim());
        int n=s.length();
        if(k>n){System.out.println(0);return;}
        final long B1=131,M1=(1L<<31)-1,B2=137,M2=(1L<<29)-3;
        long h1=0,h2=0,p1=1,p2=1;
        for(int i=0;i<k;i++){
            h1=(h1*B1+s.charAt(i))%M1;
            h2=(h2*B2+s.charAt(i))%M2;
            if(i>0){p1=p1*B1%M1;p2=p2*B2%M2;}
        }
        Set<Long> seen=new HashSet<>();
        seen.add(h1*M2+h2);
        for(int i=1;i<=n-k;i++){
            h1=((h1-p1*s.charAt(i-1)%M1+M1)*B1+s.charAt(i+k-1))%M1;
            h2=((h2-p2*s.charAt(i-1)%M2+M2)*B2+s.charAt(i+k-1))%M2;
            seen.add(h1*M2+h2);
        }
        System.out.println(seen.size());
    }
}
